<script setup>
import { computed, onBeforeUnmount, reactive, ref } from 'vue'
import { Plus } from '@lucide/vue'
import { can } from '../../permissions.js'
import { notifyError } from '../../api.js'
import { createClientId } from '../../clientId.js'
import { alarmLevels, alarmTypes, label } from '../../labels.js'
import { ruleLabWrite } from '../../rulelab/api.js'
import { candidateDraft, experimentPayload, labelConclusions, recordBody, ruleLabTime } from '../../rulelab/helpers.js'
const props=defineProps({items:{type:Array,default:()=>[]},datasets:{type:Array,default:()=>[]},labels:{type:Array,default:()=>[]},revisions:{type:Array,default:()=>[]},rules:{type:Array,default:()=>[]},devices:{type:Array,default:()=>[]},ruleId:{type:String,default:''},selectedDataset:Object})
const emit=defineEmits(['refresh','select','run'])
const rows=computed(()=>props.items.map(recordBody).filter(row=>!props.ruleId||row.candidateRuleId===props.ruleId)),dialog=ref(false),saving=ref(false),error=ref(''),form=reactive({})
const editable=computed(()=>can('menu:devices')&&can('POST /api/v1/rule-lab/experiments')),shareable=computed(()=>can('POST /api/v1/rule-lab/experiments/publish'))
const availableDatasets=computed(()=>props.datasets.filter(row=>['SUCCEEDED','PARTIAL'].includes(row.status)&&(form.scope!=='shared'||String(row.scope).toUpperCase()==='SHARED')))
const dataset=computed(()=>props.datasets.find(row=>row.id===form.datasetId))
const availableRevisions=computed(()=>props.revisions.filter(row=>(!row.rule.productId||dataset.value?.deviceIds.some(id=>props.devices.find(device=>device.id===id)?.productId===row.rule.productId))))
const targets=computed(()=>props.revisions.filter(row=>form.baselineRevisionIds?.includes(row.id)&&(!props.ruleId||row.ruleId===props.ruleId)))
const labelOptions=computed(()=>props.labels.map(recordBody).filter(row=>row.status==='CONFIRMED'&&dataset.value?.deviceIds.includes(row.deviceId)&&row.start>=dataset.value.start&&row.end<=dataset.value.end&&(form.scope!=='shared'||String(row.scope).toUpperCase()==='SHARED')))
const ruleName=id=>props.rules.find(row=>row.id===id)?.name||id
let generation=0,disposed=false,originalScope='',originalVersion=0
function targetChanged(){const baseline=props.revisions.find(row=>form.baselineRevisionIds?.includes(row.id)&&row.ruleId===form.candidateRuleId);form.candidate=candidateDraft(baseline?.rule);form.candidateEnabled=!!baseline?.rule.enabled}
function baselineChanged(ids){form.baselineRevisionIds=ids;const selected=props.revisions.filter(row=>ids.includes(row.id)),target=props.ruleId?selected.find(row=>row.ruleId===props.ruleId):selected.length===1?selected[0]:null;form.candidateRuleId=target?.ruleId||'';targetChanged()}
function edit(row){const value=row||{},policy=value.evaluationPolicy||{};Object.assign(form,{resourceId:value.resourceId||createClientId(),expectedVersion:value.revisionVersion||0,scope:String(value.scope||'personal').toLowerCase(),datasetId:value.datasetId||props.selectedDataset?.id||'',baselineRevisionIds:[...(value.baselineRevisionIds||[])],baselinePolicy:value.baselinePolicy||'FIXED_REVISIONS',candidateRuleId:value.candidateRuleId||'',candidate:candidateDraft(value.candidate),candidateEnabled:value.candidateEnabled??false,hypothesis:value.hypothesis||'',labelRevisionIds:[...(value.labelRevisionIds||[])],policyVersion:policy.version||'',toleranceSeconds:policy.toleranceMs==null?null:policy.toleranceMs/1000,matchTimeBasis:policy.matchTimeBasis||'EVENT',split:policy.split||'TUNING',representativeConfirmed:!!policy.representativeConfirmed,representativenessBasis:policy.representativenessBasis||'',holdoutResourceId:policy.holdoutResourceId||''});originalScope=form.scope;originalVersion=form.expectedVersion;if(form.scope==='shared'&&!shareable.value){form.scope='personal';form.expectedVersion=0}error.value='';dialog.value=true}
async function save(){if(saving.value)return;const token=generation;saving.value=true;error.value='';try{const body=experimentPayload(form,dataset.value,props.revisions);const row=await ruleLabWrite('experiments','','',body);if(token!==generation||disposed)return;dialog.value=false;emit('select',row);emit('refresh')}catch(cause){if(token===generation&&!disposed){error.value=cause.status===409?'实验版本已变化，请刷新后保存新的不可变版本。':cause.message;notifyError(cause)}}finally{if(token===generation)saving.value=false}}
onBeforeUnmount(()=>{disposed=true;generation++})
</script>
<template><section class="lab-stack"><div class="lab-toolbar"><p class="lab-hint">先固定基线版本与行为假设。候选正文保留禁用，只有实验分支采用本次候选启用设置。</p><ui-button v-if="editable" type="primary" size="small" @click="edit()"><Plus/>新建规则实验</ui-button></div><div class="lab-table-scroll"><ui-table :data="rows" empty-text="暂无候选实验。请先完成固定数据集。"><ui-table-column label="实验目标 / 版本" min-width="200"><template #default="{row}">{{ruleName(row.candidateRuleId)}}<p class="lab-meta">实验版本 {{row.revisionVersion}} · {{String(row.scope).toUpperCase()==='SHARED'?'共享':'个人'}}<br>候选 {{row.candidateEnabled?'仅实验启用':'实验禁用'}} · 正文已禁用</p></template></ui-table-column><ui-table-column label="行为假设 / 评价" min-width="300"><template #default="{row}">{{row.hypothesis}}<p class="lab-meta">{{row.evaluationPolicy.split==='HOLDOUT'?'留出评价':'调参比较'}} · 标签版本 {{row.labelRevisionIds.length}} 个</p></template></ui-table-column><ui-table-column label="固定数据集" min-width="170"><template #default="{row}">{{ruleLabTime(datasets.find(d=>d.id===row.datasetId)?.start)}}<p class="lab-meta">基线规则 {{row.baselineRevisionIds.length}} 条</p></template></ui-table-column><ui-table-column label="操作" width="190"><template #default="{row}"><ui-button :data-lab-experiment="row.revisionId" text size="small" @click="emit('select',items.find(item=>item.id===row.revisionId))">比较记录</ui-button><ui-button v-if="editable" text size="small" @click="edit(row)">候选新版本</ui-button><ui-button v-if="can('POST /api/v1/rule-lab/experiments/:id/runs')" :data-lab-start="row.revisionId" text size="small" @click="emit('run',items.find(item=>item.id===row.revisionId))">运行实验</ui-button></template></ui-table-column></ui-table></div></section>
 <ui-dialog v-model="dialog" :title="form.expectedVersion?'保存规则实验新版本':'新建规则实验候选'" width="min(1040px,94vw)" :close-on-click-modal="false" @close="dialog=false"><div class="lab-dialog-body"><ui-alert v-if="error" :title="error" type="error" :closable="false"/><ui-form v-if="form.candidate" label-position="top" :disabled="saving"><div class="lab-grid"><ui-form-item label="实验用途"><ui-select v-model="form.scope" @change="form.expectedVersion=form.scope===originalScope?originalVersion:0"><ui-option value="personal" label="个人比较参数"/><ui-option v-if="shareable" value="shared" label="受权共享实验"/></ui-select></ui-form-item><ui-form-item label="固定数据集" required><ui-select v-model="form.datasetId" filterable @change="form.labelRevisionIds=[]"><ui-option v-for="row in availableDatasets" :key="row.id" :value="row.id" :label="`${ruleLabTime(row.start)} 至 ${ruleLabTime(row.end)} · ${row.deviceIds.length} 个设备 · ${row.id.slice(-8)}`"/></ui-select></ui-form-item><ui-form-item label="基线政策"><ui-select v-model="form.baselinePolicy"><ui-option value="FIXED_REVISIONS" label="固定选择的不可变规则版本"/><ui-option v-if="dataset?.clockPolicy==='RECORDED_TRACE'" value="RECORDED_ACTIVATIONS" label="实际 trace 生效规则历史"/></ui-select></ui-form-item></div><ui-form-item label="不可变基线规则版本" required><ui-select v-model="form.baselineRevisionIds" multiple filterable @change="baselineChanged"><ui-option v-for="row in availableRevisions" :key="row.id" :value="row.id" :label="`${row.rule.name} · 版本 ${row.version} · ${row.rule.enabled?'启用':'禁用'} · ${ruleLabTime(row.registeredAt)}${row.initialRegistration?' · 首次登记，之前历史未知':''}`"/></ui-select></ui-form-item><ui-form-item label="替换的候选规则" required><ui-select v-model="form.candidateRuleId" :disabled="targets.length===1" @change="targetChanged"><ui-option v-for="row in targets" :key="row.id" :value="row.ruleId" :label="row.rule.name"/></ui-select></ui-form-item><ui-checkbox v-model="form.candidateEnabled">仅在本次实验计算候选规则</ui-checkbox><template v-if="form.candidate.id"><h3>候选规则正文</h3><div class="lab-grid"><ui-form-item label="候选名称" required><ui-input v-model="form.candidate.name"/></ui-form-item><ui-form-item label="告警类型"><ui-select v-model="form.candidate.alarmType"><ui-option v-for="type in alarmTypes" :key="type" :value="type" :label="label(type)"/></ui-select></ui-form-item><ui-form-item label="告警等级"><ui-select v-model="form.candidate.level"><ui-option v-for="level in alarmLevels" :key="level" :value="level" :label="label(level)"/></ui-select></ui-form-item><ui-form-item label="条件组合"><ui-select v-model="form.candidate.match"><ui-option value="all" label="全部条件满足"/><ui-option value="any" label="任一条件满足"/></ui-select></ui-form-item><ui-form-item label="持续条件（秒）"><ui-input-number v-model="form.candidate.durationSeconds" :min="0" :precision="0"/></ui-form-item></div><ui-form-item label="候选说明"><ui-input v-model="form.candidate.description" type="textarea" :rows="2"/></ui-form-item><ui-form-item label="触发条件 JSON"><ui-input v-model="form.candidate.conditions" type="textarea" :rows="5"/></ui-form-item><ui-form-item label="规则表达式（选填）"><ui-input v-model="form.candidate.expression" placeholder="填写后优先使用表达式求值"/></ui-form-item><div class="lab-grid"><ui-form-item label="恢复条件 JSON"><ui-input v-model="form.candidate.recovery" type="textarea" :rows="4"/></ui-form-item><ui-form-item label="意向联动 JSON"><ui-input v-model="form.candidate.actions" type="textarea" :rows="4"/></ui-form-item></div></template><ui-form-item label="预先固定的行为假设" required><ui-input v-model="form.hypothesis" type="textarea" :rows="3" placeholder="说明修改条件后预期改变哪些行为，以及需要核实的资料"/></ui-form-item><ui-form-item label="已确认真实标签版本（选填）"><ui-select v-model="form.labelRevisionIds" multiple filterable><ui-option v-for="row in labelOptions" :key="row.revisionId" :value="row.revisionId" :label="`${row.eventType} · ${labelConclusions[row.conclusion]} · ${ruleLabTime(row.start)} · 版本 ${row.revisionVersion}`"/></ui-select></ui-form-item><h3>共同评价政策</h3><div class="lab-grid"><ui-form-item label="匹配策略版本" required><ui-input v-model="form.policyVersion"/></ui-form-item><ui-form-item label="固定匹配容差（秒）" required><ui-input-number v-model="form.toleranceSeconds" :min="0" clearable/></ui-form-item><ui-form-item label="匹配时间依据"><ui-select v-model="form.matchTimeBasis"><ui-option value="EVENT" label="事件时间"/><ui-option value="PROCESSING" label="虚拟处理时间"/></ui-select></ui-form-item><ui-form-item label="区间用途"><ui-select v-model="form.split"><ui-option value="TUNING" label="调参比较"/><ui-option value="HOLDOUT" label="留出评价"/></ui-select></ui-form-item><ui-form-item v-if="form.split==='HOLDOUT'" label="留出区间标识"><ui-input v-model="form.holdoutResourceId" placeholder="填写同一留出评价区间的稳定标识"/></ui-form-item></div><p class="lab-hint">两分支采用相同的已核实正负区间与统一排除。按固定容差一对一匹配；额外告警周期各自计入提醒，不临时合并。</p><ui-checkbox v-model="form.representativeConfirmed">已核实正负区间的代表性与完整覆盖依据</ui-checkbox><ui-form-item v-if="form.representativeConfirmed" label="正负代表性与覆盖依据" required><ui-input v-model="form.representativenessBasis" type="textarea" :rows="3"/></ui-form-item><p class="lab-hint">资料不足或初态未知时，结果只报告行为差异，不能解释为准确率或召回率提升。</p></ui-form></div><template #footer><ui-button :disabled="saving" @click="dialog=false">取消</ui-button><ui-button type="primary" :loading="saving" @click="save">保存禁用候选与实验版本</ui-button></template></ui-dialog>

</template>
